package app.codex.f5voice.compat.com.android.integrated;
import android.app.Activity;import android.os.*;import android.widget.*;
public final class RecoverySettingsActivity extends Activity {
 private final Handler main=new Handler();private TextView status,migration;private final Runnable refresh=new Runnable(){public void run(){status.setText(RecoveryState.prefs(RecoverySettingsActivity.this).getString("status","尚未启用自动恢复"));migration.setText(MigrationClient.summary(RecoverySettingsActivity.this));main.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(TvStyle.dp(this,40),TvStyle.dp(this,24),TvStyle.dp(this,40),TvStyle.dp(this,24));root.addView(TvStyle.text(this,"VoxKey 自动恢复",27,TvStyle.TEXT));status=TvStyle.text(this,"",17,TvStyle.TEXT);root.addView(status);migration=TvStyle.text(this,"",15,TvStyle.MUTED);root.addView(migration);root.addView(TvStyle.text(this,DeviceProfile.f5()?"唤醒时恢复，本次切换不抢回":"实验功能：此机型的开机恢复尚未验证",15,TvStyle.MUTED));Button enable=TvStyle.button(this,"启用自动恢复",()->RecoveryState.enable(this));root.addView(enable);root.addView(TvStyle.button(this,"立即恢复",()->{if(RecoveryState.enabled(this))RecoveryState.manual(this);else RecoveryState.enable(this);}));root.addView(TvStyle.button(this,"停用自动恢复",()->RecoveryState.disable(this)));root.addView(TvStyle.button(this,"重试迁移",()->MigrationClient.start(this,null)));root.addView(TvStyle.button(this,"返回",()->finish()));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);setContentView(TvStyle.scene(this,scroll));enable.requestFocus();}
 @Override public void onResume(){super.onResume();main.post(refresh);}
 @Override public void onPause(){main.removeCallbacks(refresh);super.onPause();}
}
